use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicUsize,Ordering};
static COUNT:AtomicUsize=AtomicUsize::new(0);
static BYTES:AtomicUsize=AtomicUsize::new(0);
struct Alloc;
unsafe impl GlobalAlloc for Alloc {
 unsafe fn alloc(&self,l:Layout)->*mut u8{COUNT.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(l.size(),Ordering::Relaxed);unsafe{System.alloc(l)}}
 unsafe fn alloc_zeroed(&self,l:Layout)->*mut u8{COUNT.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(l.size(),Ordering::Relaxed);unsafe{System.alloc_zeroed(l)}}
 unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{COUNT.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(n,Ordering::Relaxed);unsafe{System.realloc(p,l,n)}}
 unsafe fn dealloc(&self,p:*mut u8,l:Layout){unsafe{System.dealloc(p,l)}}
}
#[global_allocator]static A:Alloc=Alloc;
fn main(){
 let args:Vec<_>=std::env::args().collect();
 if args[1]=="generate" {
  let source=std::fs::read_to_string(&args[2]).unwrap();
  let target=toucan_target::Target::parse(&args[3]).unwrap();
  let unit=toucan_semantic::analyze(&source,target).unwrap();
  let options=toucan_bindings::Options{rust_target:toucan_bindings::RustTarget::RUST_1_64,rustified_enums:true,..Default::default()};
  let out=toucan_bindings::generate(&unit,&options).unwrap();
  std::fs::write(&args[4],out.source).unwrap();
 }else if args[1]=="allocations" {
  let mut many=String::from("typedef unsigned long Size;struct Large{");
  for n in 0..100{many.push_str(&format!("Size field{n};"));}
  many.push_str("};");
  for n in 0..100{many.push_str(&format!("Size function{n}(struct Large*);"));}
  let cases=[("scalar","int f(int,double);typedef unsigned long Size;Size size(void);"),
  ("record","typedef struct Point{int x,y;}Point;typedef struct Rect{Point a,b;}Rect;void move(Rect*,int,int);"),
  ("large",many.as_str()),("bitfields","struct Flags{unsigned a:1,b:3,c:12;int count;};void use_flags(struct Flags*);typedef void(*Callback)(struct Flags*);")];
  for (name,source) in cases {
   let unit=toucan_semantic::analyze(source,toucan_target::Target::X86_64UnknownLinuxGnu).unwrap();
   let options=toucan_bindings::Options::default();
   COUNT.store(0,Ordering::SeqCst);BYTES.store(0,Ordering::SeqCst);
   let out=toucan_bindings::generate(&unit,&options).unwrap();
   let count=COUNT.load(Ordering::SeqCst);let bytes=BYTES.load(Ordering::SeqCst);
   if let Some(directory)=args.get(2){std::fs::write(std::path::Path::new(directory).join(format!("{name}.rs")),&out.source).unwrap();}
   println!("{name} {count} {bytes} {}",out.source.len());
  }
 }
}

